function drawAtlas(atlas, indices) {
  const { width, height } = atlas.texture;
  const rows = [];
  for (let y = 0; y < height; y++) {
    rows.push(new Array(width).fill("."));
  }
  const rect = new import__27.BoundingRectangle();
  for (const index of indices) {
    atlas.computeTextureCoordinates(index, rect);
    rect.x *= width;
    rect.y *= height;
    rect.width *= width;
    rect.height *= height;
    for (let dx = 0; dx < rect.width; dx++) {
      const x = rect.x + dx;
      for (let dy = 0; dy < rect.height; dy++) {
        const y = rect.y + dy;
        rows[y][x] = index;
      }
    }
  }
  return rows.reverse().map((row) => row.join("")).join("\n");
}

