var import__206 = __toESM(require_Cesium(), 1);
describe("Core/HermitePolynomialApproximation", function() {
  const xTable = [0, 60, 120, 180, 240, 300, 360, 420];
  const yTable = [
    13378137,
    0,
    133741283576279e-7,
    0,
    133621048328212e-7,
    0,
    133420736310691e-7,
    0,
    133140467567223e-7,
    0,
    13278041005799e-6,
    0,
    132340779559193e-7,
    0,
    13182183953374e-6,
    0
  ];
  const dyTable = [
    0,
    0,
    -133.614738921601,
    0,
    -267.149404854867,
    0,
    -400.523972797808,
    0,
    -533.658513692378,
    0,
    -666.473242324565,
    0,
    -798.888565138278,
    0,
    -930.82512793439,
    0
  ];
  const yTableCombined = new Array(yTable.length * 2);
  for (let i = 0; i < yTable.length / 2; ++i) {
    yTableCombined[i * 4 + 0] = yTable[i * 2 + 0];
    yTableCombined[i * 4 + 1] = yTable[i * 2 + 1];
    yTableCombined[i * 4 + 2] = dyTable[i * 2 + 0];
    yTableCombined[i * 4 + 3] = dyTable[i * 2 + 1];
  }
  const x = 100;
  it("interpolating produces correct results.", function() {
    const result = import__206.HermitePolynomialApproximation.interpolateOrderZero(
      x,
      xTable,
      yTableCombined,
      4
    );
    const expectedResult = 13367002870928625e-9;
    expect(result[0]).toEqualEpsilon(expectedResult, 1e-6);
  });
  it("interpolating produces correct results with a result parameter.", function() {
    const result = new Array(4);
    const returnedResult = import__206.HermitePolynomialApproximation.interpolateOrderZero(
      x,
      xTable,
      yTableCombined,
      4,
      result
    );
    const expectedResult = 13367002870928625e-9;
    expect(result).toBe(returnedResult);
    expect(result[0]).toEqualEpsilon(expectedResult, 1e-6);
  });
  it("getRequiredDataPoints should be 1 more than degree, except for 0, which requires 2", function() {
    expect(import__206.HermitePolynomialApproximation.getRequiredDataPoints(0)).toEqual(2);
    expect(import__206.HermitePolynomialApproximation.getRequiredDataPoints(1)).toEqual(2);
    expect(import__206.HermitePolynomialApproximation.getRequiredDataPoints(2)).toEqual(3);
    expect(import__206.HermitePolynomialApproximation.getRequiredDataPoints(3)).toEqual(4);
    expect(import__206.HermitePolynomialApproximation.getRequiredDataPoints(3, 1)).toEqual(
      2
    );
    expect(import__206.HermitePolynomialApproximation.getRequiredDataPoints(5, 1)).toEqual(
      3
    );
    expect(import__206.HermitePolynomialApproximation.getRequiredDataPoints(7, 1)).toEqual(
      4
    );
  });
  it("higher order interpolation produces correct results.", function() {
    const result = import__206.HermitePolynomialApproximation.interpolate(
      x,
      xTable,
      yTableCombined,
      2,
      1,
      1
    );
    const expectedResult = [13367002870928625e-9, 0, -222.65168787012135, 0];
    expect(result).toEqualEpsilon(expectedResult, 1e-8);
  });
});

