  it("factorial produces the correct results", function() {
    const factorials2 = [
      1,
      1,
      2,
      6,
      24,
      120,
      720,
      5040,
      40320,
      362880,
      3628800,
      39916800,
      479001600,
      6227020800,
      87178291200,
      1307674368e3,
      20922789888e3,
      355687428096e3,
      6402373705728e3,
      121645100408832e3,
      243290200817664e4,
      5109094217170944e4,
      11240007277776077e5,
      // eslint-disable-next-line no-loss-of-precision
      2585201673888498e7,
      // eslint-disable-next-line no-loss-of-precision
      6204484017332394e8
    ];
    const length2 = factorials2.length;
    let i;
    const indices = [];
    for (i = 0; i < length2; i++) {
      indices.push(i);
    }
    for (i = 0; i < length2; i++) {
      const tmp = indices[i];
      const randomIndex = Math.floor(Math.random() * length2);
      indices[i] = indices[randomIndex];
      indices[randomIndex] = tmp;
    }
    for (i = 0; i < length2; i++) {
      const index = indices[i];
      expect(import__225.Math.factorial(index)).toEqual(factorials2[index]);
    }
  });
