    it("propagates tile transform down the tree", function() {
      const b3dmCommands = 1;
      const i3dmCommands = scene2.context.instancedArrays ? 1 : 25;
      const totalCommands = b3dmCommands + i3dmCommands;
      return Cesium3DTilesTester_default.loadTileset(
        scene2,
        tilesetWithTransformsUrl
      ).then(function(tileset) {
        const statistics2 = tileset._statistics;
        const root = tileset.root;
        const rootTransform = import__373.Matrix4.unpack(root._header.transform);
        const child = root.children[0];
        const childTransform = import__373.Matrix4.unpack(child._header.transform);
        let computedTransform = import__373.Matrix4.multiply(
          rootTransform,
          childTransform,
          new import__373.Matrix4()
        );
        expect(statistics2.numberOfCommands).toBe(totalCommands);
        expect(root.computedTransform).toEqual(rootTransform);
        expect(child.computedTransform).toEqual(computedTransform);
        const tilesetTransform = import__373.Matrix4.fromTranslation(
          new import__373.Cartesian3(0, 1, 0)
        );
        tileset.modelMatrix = tilesetTransform;
        computedTransform = import__373.Matrix4.multiply(
          tilesetTransform,
          computedTransform,
          computedTransform
        );
        scene2.renderForSpecs();
        expect(child.computedTransform).toEqual(computedTransform);
        tileset.modelMatrix = import__373.Matrix4.fromTranslation(
          new import__373.Cartesian3(0, 1e5, 0)
        );
        scene2.renderForSpecs();
        expect(statistics2.numberOfCommands).toBe(0);
        tileset.modelMatrix = import__373.Matrix4.IDENTITY;
        scene2.renderForSpecs();
        expect(statistics2.numberOfCommands).toBe(totalCommands);
        child.transform = import__373.Matrix4.fromTranslation(
          new import__373.Cartesian3(0, 1e5, 0)
        );
        scene2.renderForSpecs();
        expect(statistics2.numberOfCommands).toBe(1);
        child.transform = import__373.Matrix4.IDENTITY;
        scene2.renderForSpecs();
        expect(statistics2.numberOfCommands).toBe(totalCommands);
      });
    });
