      fog.update(frameState2);
      console.log(frameState2);
      expect(frameState2.fog.enabled).toBeTrue();
      expect(frameState2.fog.density).toBeGreaterThan(0);
      expect(frameState2.fog.sse).toEqual(11);
      expect(frameState2.fog.visualDensityScalar).toEqual(12);
      expect(frameState2.fog.minimumBrightness).toEqual(13);
