// packages/engine/Specs/Scene/TerrainSpec.js
var import__529 = __toESM(require_Cesium(), 1);
describe("Scene/Terrain", function() {
  it("constructor throws without terrain promise", function() {
    expect(() => new import__529.Terrain()).toThrowDeveloperError();
  });
  it("does not throw on error", function() {
    expect(() => {
      const terrain = new import__529.Terrain(Promise.reject(new Error("Fail")));
    }).not.toThrow();
  });
  it("readyEvent handles terrain promise success", async function() {
    let resolve;
    const promise = new Promise((r) => {
      resolve = r;
    });
    const terrain = new import__529.Terrain(promise);
    const terrainProvider = new import__529.EllipsoidTerrainProvider();
    let wasCalled = false;
    terrain.readyEvent.addEventListener((provider) => {
      expect(provider).toBe(terrainProvider);
      wasCalled = true;
    });
    resolve(terrainProvider);
    await promise;
    expect(wasCalled).toBeTrue();
    expect(terrain.provider).toBe(terrainProvider);
  });
  it("errorEvent handles terrain promise failure", async function() {
    let reject;
    const promise = new Promise((resolve, r) => {
      reject = r;
    });
    const terrain = new import__529.Terrain(promise);
    const error = new Error("Fail");
    let wasCalled = false;
    terrain.errorEvent.addEventListener((e) => {
      expect(e).toBe(error);
      wasCalled = true;
    });
    reject(error);
    await expectAsync(promise).toBeRejected();
    expect(wasCalled).toBeTrue();
  });
});

